css:
.ra { font-family: "Inter", -apple-system, "Segoe UI", sans-serif; color: #1e293b; font-size: 13px; line-height: 1.55; }
.ra h1 { text-align: center; font-size: 22px; letter-spacing: 0.06em; text-transform: uppercase; margin: 0 0 4px; }
.ra h2 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.05em; color: #4f46e5; margin: 22px 0 8px; border-bottom: 1px solid #e2e8f0; padding-bottom: 4px; }
.ra-center { text-align: center; }
.ra-muted { color: #64748b; }
.ra-small { font-size: 11px; margin-top: 24px; }
.ra-label { font-size: 11px; font-weight: 700; text-transform: uppercase; color: #94a3b8; margin-bottom: 4px; }
.ra-parties { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin: 12px 0; }
.ra-parties > div { background: #f8fafc; border-radius: 8px; padding: 12px 14px; }
.ra-terms { width: 100%; border-collapse: collapse; }
.ra-terms td { padding: 6px 4px; border-bottom: 1px solid #f1f5f9; vertical-align: top; }
.ra-terms td:first-child { width: 32%; color: #64748b; }
.ra-list { padding-left: 18px; }
.ra-list li { margin-bottom: 6px; }
.ra-sign { display: grid; grid-template-columns: 1fr 1fr; gap: 40px 48px; margin-top: 48px; }
.ra-line { border-top: 1px solid #1e293b; height: 36px; }
.ra-esign { border: 1px solid #a7f3d0; background: #ecfdf5; border-radius: 8px; padding: 10px 12px; font-size: 12px; }
